// Sinopsis oficiales de Disney+ (pestaña "Details" de cada titulo, leidas el
// 2026-11-11 desde la cuenta del usuario). EN: texto oficial, solo sin los avisos
// tecnicos ("Some flashing lights...", "Contains tobacco depictions") ni las
// listas de creditos de reparto/produccion. ES: traduccion propia, no literal,
// respetando las reglas del sitio (titulos de obras y nombres de equipos sin
// traducir). Las entregas que no estan en Disney+ (Spider-Man: Homecoming,
// Spider-Man: Brand New Day, Runaways, Slingshot, Peter's To-Do List y las que
// aun no se estrenan) no tienen entrada y usan la sinopsis de TMDB.
// Las sinopsis de serie que describen solo una temporada concreta se asignan
// solo a esa temporada.

interface Synopsis {
  en: string;
  es: string;
}

